import SwiftUI
struct ProjectsView:View{@EnvironmentObject var s:AppStore;@State var add=false;var body:some View{NavigationStack{List{ForEach(s.projects){p in HStack{Circle().fill(p.color.color).frame(width:12,height:12);VStack(alignment:.leading){Text(p.name).strikethrough(p.isClosed);Text("\(p.dailyMinutes) min/day").font(.caption)};Spacer();Button(p.isClosed ? "Reopen":"Close"){s.toggleProject(p)}.buttonStyle(.borderless)}}.onDelete{for i in $0{s.deleteProject(s.projects[i])}}}.navigationTitle("Projects").toolbar{Button{add=true}label:{Image(systemName:"plus")}}.sheet(isPresented:$add){AddProject()}}}}
struct AddProject:View{@EnvironmentObject var s:AppStore;@Environment(\.dismiss)var dismiss;@State var n="";@State var m=60;@State var c=ProjectColor.blue;var body:some View{NavigationStack{Form{TextField("Project name",text:$n);Picker("Daily allocation",selection:$m){ForEach([15,30,45,60,90,120],id:\.self){Text("\($0) minutes")}};Picker("Color",selection:$c){ForEach(ProjectColor.allCases){Text($0.rawValue.capitalized).tag($0)}}}.navigationTitle("New Project").toolbar{ToolbarItem(placement:.cancellationAction){Button("Cancel"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Add"){s.addProject(n,m,c);dismiss()}.disabled(n.isEmpty)}}}}}